<script>(function(){var form=document.getElementById('etcv-draft-form');var tabs=document.querySelectorAll('[data-etcv-tab]');var sections=form?form.querySelectorAll(':scope > .etcv-section'):[];function key(s){var h=s.querySelector('h2');var t=h?h.textContent.toLowerCase():'';if(t.indexOf('hotel')>=0||t.indexOf('accommodation')>=0)return'hotel';if(t.indexOf('flight')>=0)return'flight';if(t.indexOf('transport')>=0)return'transport';if(t.indexOf('visa')>=0)return'visa';if(t.indexOf('ticket')>=0)return'tickets';return'instructions';}function selectTab(name){tabs.forEach(function(b){var on=b.dataset.etcvTab===name;b.setAttribute('aria-selected',on?'true':'false');});sections.forEach(function(s){s.classList.toggle('etcv-tab-hidden',name!=='all'&&key(s)!==name);});}tabs.forEach(function(b,i){b.addEventListener('click',function(){selectTab(b.dataset.etcvTab);});b.addEventListener('keydown',function(e){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();var n=(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[n].focus();selectTab(tabs[n].dataset.etcvTab);}});});document.querySelectorAll('[data-edit-path]').forEach(function(i){i.addEventListener('input',function(){var path=i.dataset.editPath;document.querySelectorAll('[data-preview-path]').forEach(function(n){if(n.dataset.previewPath===path)n.textContent=i.value;});});});var preview=document.getElementById('draftPreview');document.getElementById('previewChanges')?.addEventListener('click',function(){if(preview&&preview.tagName.toLowerCase()==='details')preview.open=true;preview?.scrollIntoView({behavior:'smooth'});});})();</script>
